<?php
namespace App\Http\Controllers;
use App\Models\{User,Role};use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\Rule;
class UserController {public function index(){return view('users.index',['users'=>User::forCompany(auth()->user()->company_id)->with('roles')->get(),'roles'=>Role::forCompany(auth()->user()->company_id)->get()]);}public function store(Request $r){$c=$r->user()->company_id;$d=$r->validate(['name'=>'required|string|max:255','email'=>['required','email',Rule::unique('users')->where(fn($q)=>$q->where('company_id',$c))],'password'=>'required|string|min:12','role_ids'=>'required|array|min:1','role_ids.*'=>'integer']);$roles=Role::forCompany($c)->whereIn('id',$d['role_ids'])->pluck('id');if($roles->count()!==count(array_unique($d['role_ids'])))abort(404);$u=User::create(['company_id'=>$c,'name'=>$d['name'],'email'=>$d['email'],'password'=>Hash::make($d['password']),'active'=>true]);$u->roles()->sync($roles);return back()->with('ok','User created.');}public function update(Request $r,User $user){if($user->id===$r->user()->id&&$r->has('active')&&!$r->boolean('active'))return back()->withErrors(['active'=>'You cannot deactivate your own account.']);$d=$r->validate(['name'=>'required|string|max:255','active'=>'nullable|boolean','role_ids'=>'required|array|min:1','role_ids.*'=>'integer']);$roles=Role::forCompany($r->user()->company_id)->whereIn('id',$d['role_ids'])->pluck('id');if($roles->count()!==count(array_unique($d['role_ids'])))abort(404);$user->update(['name'=>$d['name'],'active'=>$r->boolean('active')]);$user->roles()->sync($roles);return back()->with('ok','User updated.');}}
